insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked) values ('parco-abbazia-monteveglio','Parco regionale Abbazia di Monteveglio','natura','Parco con abbazia medievale e centro visite nella torre del castello; sentiero accessibile che parte dai prati attorno. Itinerari corti o più lunghi a seconda delle età.',4,17,'Piccoli: sentiero breve vicino ai prati. Grandi: itinerari più lunghi nel parco.','outdoor','dry_only','free','Ingresso al parco libero (centro visite da verificare)',150,false,'Centro visite: orari da verificare (tel. 051 6701044)','https://www.bolognawelcome.com/it/luoghi/parchi-e-giardini/parco-regionale-dellabbazia-di-monteveglio','da_verificare',true,'2026-11-01') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked) values ('chiusa-di-casalecchio','Chiusa di Casalecchio e Parco della Chiusa','natura','Diga storica sul Reno con passeggiata sul fiume e parco della Chiusa, ex tenuta Sampieri Talon. Spazio per pic-nic e per capire come il canale muoveva i mulini di Bologna.',3,17,'Piccoli: acqua e prati. Grandi: storia del canale e delle sue funzioni.','outdoor','dry_only','free','Passeggiata sul fiume; costi e visite guidate del Consorzio da verificare',90,false,null,'https://www.italia.it/it/emilia-romagna/bologna/chiusa-di-casalecchio','da_verificare',true,'2026-11-01') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked) values ('portico-san-luca','Portico e Santuario di San Luca','gita','Salita di circa 3,6-3,8 km sotto il portico più lungo del mondo fino al santuario, con sosta all''Arco del Meloncello. Si può dividere in tappe o scegliere il trenino turistico.',4,17,'Piccoli: contano gli archi e fanno pause. Grandi: arrivano in cima e scendono a piedi.','outdoor','any','free','Portico gratuito; trenino San Luca Express a pagamento',180,false,'Orari del santuario non verificati (santuariodisanluca.it)','https://www.italia.it/it/emilia-romagna/bologna/santuario-madonna-di-san-luca','da_verificare',true,'2026-11-01') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked) values ('ciclovia-del-navile','Ciclovia del Canale Navile','sport','Percorso in bici lungo il canale Navile da Bologna verso Bentivoglio: piste, sterrati e strade secondarie, con tappe come Villa Smeraldi e Oasi La Rizza. Si accorcia a piacere.',5,17,'Piccoli: tratti brevi e pause. Grandi: tappe più lunghe fino a Bentivoglio.','outdoor','dry_only','free','Accesso libero',180,false,'Percorso lungo il canale: nessun orario','https://emiliaromagnaturismo.it/en/itineraries/navile-cycle-route','da_verificare',true,'2026-11-01') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked) values ('parco-avventura-cavaioni','Cavaioni Park (parco avventura)','sport','Parco avventura sugli alberi con percorsi baby e junior (da 100 cm) e percorsi avventura (da 140 cm): ogni fratello trova il proprio livello. Apertura stagionale.',4,17,'Piccoli: percorsi baby da 100 cm. Grandi: percorsi avventura da 140 cm.','outdoor','dry_only','mid','Dati 2024: ridotto (da 100 cm) 20 €, intero (da 140 cm) 25 €',180,null,'Stagionale: nel 2024 aprile-ottobre (weekend in primavera e autunno, tutti i giorni in estate tranne lun); gruppi su prenotazione','https://www.bolognawelcome.com/it/luoghi/parchi-tematici/parco-avventura-cavaioni','draft',true,'2026-11-01') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked) values ('fattoria-didattica-monte-san-pietro','Visita in fattoria didattica con merenda (Monte San Pietro)','fattoria','Visita di un''ora in una piccola fattoria: asino, capra, coniglio e agnello da accarezzare e dare da mangiare, poi merenda casalinga. Per famiglie, gruppi fino a 15 persone.',2,14,'Piccoli: accarezzano gli animali. Grandi: imparano come si curano e cosa mangiano.','outdoor','dry_only','mid','Da 15 € a persona',60,true,'Esperienza proposta da gennaio a settembre (non attiva ott-dic); indirizzo comunicato dopo la prenotazione','https://freedome.it/attivita/visita-fattoria-didattica-merenda-monte-san-pietro-bologna/','draft',true,'2026-11-01') on conflict (slug) do nothing;
insert into activities (slug,title,category,description,min_age,max_age,multi_age_note,setting,weather_fit,cost_band,price_note,duration_min,booking_required,opening_note,source_url,status,is_demo,last_checked) values ('parco-gessi-bolognesi-farneto','Parco dei Gessi Bolognesi e Calanchi dell''Abbadessa (Farneto)','natura','Parco regionale con affioramenti di gesso, doline e oltre 130 grotte, sito UNESCO, a meno di 20 km dal centro. Sentieri per camminare in famiglia; visite alle grotte da verificare.',6,17,'Piccoli: sentieri semplici e doline. Grandi: geologia e grotte (se concordate).','outdoor','dry_only','free','Accesso al parco libero; visite in grotta da verificare',150,null,null,'https://bolognawelcome.com/en/places/parks-and-gardens/parco-dei-gessi--2','da_verificare',true,'2026-11-01') on conflict (slug) do nothing;
